// Models generated by Claude because this is boring work :)

/** GET /public/collection/v1/objects  (also used for ?departmentIds= and ?metadataDate=) */
export type ObjectsResponse = {
  /** Total number of publicly-available objects */
  total: number;
  objectIDs: number[];
};

/** GET /public/collection/v1/search and /public/collection/v1.1/search
 *  (v1.1 is paginated via offset/limit; v1 is deprecated and retires 2026-10-01) */
export type SearchResponse = {
  /** Total number of matching objects across all pages */
  total: number;
  objectIDs: number[];
};

/** GET /public/collection/v1/departments */
export type DepartmentsResponse = {
  departments: Department[];
};

export type Department = {
  departmentId: number;
  displayName: string;
};

/** GET /public/collection/v1/objects/[objectID] */
export type MetObject = {
  objectID: number;
  isHighlight: boolean;
  accessionNumber: string;
  accessionYear: string;
  isPublicDomain: boolean;
  primaryImage: string;
  primaryImageSmall: string;
  additionalImages: string[];
  constituents: Constituent[] | null;
  department: string;
  objectName: string;
  title: string;
  culture: string;
  period: string;
  dynasty: string;
  reign: string;
  portfolio: string;
  artistRole: string;
  artistPrefix: string;
  artistDisplayName: string;
  artistDisplayBio: string;
  artistSuffix: string;
  artistAlphaSort: string;
  artistNationality: string;
  artistBeginDate: string;
  artistEndDate: string;
  /** Currently contains female designations only */
  artistGender: string;
  artistWikidata_URL: string;
  artistULAN_URL: string;
  objectDate: string;
  objectBeginDate: number;
  objectEndDate: number;
  medium: string;
  dimensions: string;
  /** Documented as "float", but the example shows an array of parsed dimensions (cm) */
  dimensionsParsed?: DimensionParsed[];
  measurements: Measurement[] | null;
  creditLine: string;
  geographytype: string;
  city: string;
  state: string;
  county: string;
  country: string;
  region: string;
  subregion: string;
  locale: string;
  locus: string;
  excavation: string;
  river: string;
  classification: string;
  rightsAndReproduction: string;
  linkResource: string;
  /** ISO datetime, e.g. "2020-09-14T12:26:37.48Z" */
  metadataDate: string;
  repository: string;
  objectURL: string;
  tags: Tag[] | null;
  objectWikidata_URL: string;
  isTimelineWork: boolean;
  GalleryNumber: string;
};

export type Constituent = {
  constituentID: number;
  role: string;
  name: string;
  constituentULAN_URL: string;
  constituentWikidata_URL: string;
  /** Currently contains female designations only */
  gender: string;
};

export type DimensionParsed = {
  element: string;
  dimensionetype: string;
  /** In centimeters */
  dimension: number;
};

export type Measurement = {
  elementName: string;
  elementDescription: string | null;
  elementMeasurements: ElementMeasurements;
};

/** Spatial measurements in cm; weights in kg */
export type ElementMeasurements = {
  Height?: number;
  Width?: number;
  Length?: number;
  [key: string]: number | undefined;
};

export type Tag = {
  term: string;
  AAT_URL: string;
  Wikidata_URL: string;
};